  ui_story_30680601_158_dialog_content = "Está bien, no hay forma de que me crea eso.",
  ui_story_30680601_159_dialog_content = "¡Yo, Jomu!",
  ui_story_30680601_160_dialog_content = "¡Pues mira quién es! ¡Wendy, el pajarito más brillante de todo el desierto!",
