  ui_story_30680601_170_dialog_content = "Cuando se trata de negocios, la mejor manera de ganar dinero es cuando todas las partes se benefician.",
  ui_story_30680601_171_dialog_content = "Y en el cruel mundo de los negocios, quien tiene información lo controla todo.",
