  ui_story_30680601_177_dialog_content = "Está bien, me rindo...",
  ui_story_30680601_178_dialog_content = "Nunca pensé que Jomu estaría de acuerdo con algo como esto. Aunque supongo que hacer tratos ES su especialidad.",
  ui_story_30680601_179_dialog_content = "Bien, lo admito: realmente eres un genio de las ventas.",
  ui_story_30680601_180_dialog_content = "Finalmente dando la vuelta, ¿eh? En ese caso, ¿puedo interesarte en una suscripción al periódico?",
  ui_story_30680601_181_dialog_content = "Después de todo, sería bastante grosero de tu parte si no lo hicieras después de que trabajé tan duro para convencerte...",
  ui_story_30680601_182_dialog_content = "Además, ¿no quieres saber más sobre esa columna normal de Caelestite?",
  ui_story_30680601_183_dialog_content = "Ah, y solo para su información, ¡todos en Rediesel Wrench están leyendo los periódicos ahora!",
  ui_story_30680601_184_dialog_content = "No querrás quedarte atrás de ese grupo de cabezas huecas, ¿verdad?",
  ui_story_30680601_185_dialog_content = "¡Sí, sí, lo entiendo!",
  ui_story_30680601_186_dialog_content = "Puaj. Tendré que volver por ese juego de mesa en otro momento...",
  ui_story_30680601_187_dialog_content = "PlayerName—",
  ui_story_30680601_188_dialog_content = "V-Vicio?!",
  ui_story_30680601_189_dialog_content = "¿Qué te ha estado tomando tanto tiempo? ¿Mmm? ¡Oye, Wendy!",
